spec fn is_sign(x: i64, r: i64) -> bool { (x > 0 ==> r == 1) && (x < 0 ==> r == -1) && (x == 0 ==> r == 0) }

spec fn nonzero(r: i64) -> bool { r != 0 }

#[effects(pure)]
#[uses(is_sign, nonzero)]
fn sign(x: i64) -> (r: i64)
    ensures is_sign(x, r), nonzero(r),
{
    0
}

