#[summary("impossibility certificate")]
mod bmb_cert {
    spec fn never() -> bool { false }

    spec fn witness(x: i64) -> bool { x == 0 }

    #[effects(pure)]
    #[uses(witness, tasks::is_sign, tasks::nonzero)]
    fn refute(x: i64) -> ()
        requires witness(x),
        ensures never(),
    {
        let r: i64 = tasks::sign(x);
    }

    #[effects(pure)]
    #[uses(witness)]
    fn reach() -> () {
        refute(0)
    }
}

